def transform(grid):
    h,w=len(grid),len(grid[0]); out=[[0]*w for _ in range(h)]; used=set()
    # Identify the non-overlapping 2x2 squares first.
    for r in range(h-1):
        for c in range(w-1):
            pts={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
            if all(grid[i][j]==8 for i,j in pts) and not pts&used:
                for i,j in pts: out[i][j]=1
                used |= pts
    # Color remaining L-triominoes according to their missing corner, following demos.
    # color 2: missing top-left; 3: missing bottom-left; 4: missing top-right.
    colors={(0,1,1,1):2,(1,1,0,1):3,(1,0,1,1):4,(1,1,1,0):2}
    for r in range(h-1):
        for c in range(w-1):
            pts=[(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
            bits=tuple(int(grid[i][j]==8 and (i,j) not in used) for i,j in pts)
            if bits in colors:
                for (i,j),b in zip(pts,bits):
                    if b: out[i][j]=colors[bits]; used.add((i,j))
    for r in range(h):
        for c in range(w):
            if grid[r][c]==8 and out[r][c]==0: out[r][c]=1
    return out
