def transform(grid):
    h,w=len(grid),len(grid[0])
    cells={(r,c) for r in range(h) for c in range(w) if grid[r][c]==8}
    # Pieces observed in demonstrations: 2x2 squares and three-cell Ls.
    # Cover the foreground exactly, preferring the largest possible squares.
    pieces=[]
    for r in range(h-1):
        for c in range(w-1):
            square=frozenset(((r,c),(r,c+1),(r+1,c),(r+1,c+1)))
            if square <= cells: pieces.append((square,1))
            for missing,color in [((r,c),2),((r,c+1),4),((r+1,c),3),((r+1,c+1),2)]:
                tri=square-{missing}
                if tri <= cells: pieces.append((frozenset(tri),color))
    bycell={p:[] for p in cells}
    for piece in pieces:
        for cell in piece[0]: bycell[cell].append(piece)
    def solve(rem):
        if not rem: return []
        cell=min(rem,key=lambda x:sum(1 for p in bycell[x] if p[0]<=rem))
        opts=[p for p in bycell[cell] if p[0]<=rem]
        opts.sort(key=lambda p:(-len(p[0]),p[1]))
        for p in opts:
            rest=solve(rem-p[0])
            if rest is not None: return [p]+rest
        return None
    decomposition=solve(cells)
    out=[[0]*w for _ in range(h)]
    if decomposition:
        for shape,color in decomposition:
            for r,c in shape: out[r][c]=color
    return out
