def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = frozenset(((r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)))
            if square <= cells:
                pieces.append((square, 1))
            # L triomino color corresponds to the omitted corner.
            for missing, color in (((r, c), 2), ((r, c + 1), 4), ((r + 1, c), 3), ((r + 1, c + 1), 4)):
                tri = square - {missing}
                if tri <= cells:
                    pieces.append((frozenset(tri), color))

    by_cell = {p: [] for p in cells}
    for piece in pieces:
        for cell in piece[0]:
            by_cell[cell].append(piece)

    def cover(remaining):
        if not remaining:
            return []
        cell = min(remaining, key=lambda p: sum(1 for piece in by_cell[p] if piece[0] <= remaining))
        options = [piece for piece in by_cell[cell] if piece[0] <= remaining]
        options.sort(key=lambda piece: (-len(piece[0]), piece[1]))
        for piece in options:
            rest = cover(remaining - piece[0])
            if rest is not None:
                return [piece] + rest
        return None

    decomposition = cover(cells)
    out = [[0] * w for _ in range(h)]
    if decomposition is not None:
        for shape, color in decomposition:
            for r, c in shape:
                out[r][c] = color
    return out
